import React, { useState } from "react";

function ShapAttributionChart({ deductions = [] }) {
  const [filter, setFilter] = useState("all");

  const filteredDeductions = deductions.filter((d) => {
    if (filter === "additive") return d.type === "additive";
    if (filter === "nutrient") return d.type === "nutrient";
    return true;
  });

  const maxAbsPoints = deductions.reduce((max, d) => Math.max(max, Math.abs(d.points_deducted || 0)), 1);

  return (
    <div className="card glass shap-card">
      <div className="card-header-between">
        <div>
          <h2>📊 Local Feature Attributions (SHAP)</h2>
          <p className="card-sub">
            Exact point deductions assigned to individual additives and excess nutrients.
          </p>
        </div>
        <div className="filter-pill-group">
          <button
            className={`filter-pill ${filter === "all" ? "active" : ""}`}
            onClick={() => setFilter("all")}
          >
            All ({deductions.length})
          </button>
          <button
            className={`filter-pill ${filter === "additive" ? "active" : ""}`}
            onClick={() => setFilter("additive")}
          >
            Additives
          </button>
          <button
            className={`filter-pill ${filter === "nutrient" ? "active" : ""}`}
            onClick={() => setFilter("nutrient")}
          >
            Nutrients
          </button>
        </div>
      </div>

      {deductions.length === 0 ? (
        <div className="empty-notice">
          <span>🛡️</span>
          <p>No negative feature attributions detected! Product has zero high-risk additives or excess nutrients.</p>
        </div>
      ) : (
        <div className="deductions-list">
          {filteredDeductions.map((item, index) => {
            const points = item.points_deducted || 0;
            const barWidthPercent = Math.min(100, Math.round((Math.abs(points) / maxAbsPoints) * 100));

            return (
              <div key={index} className="deduction-row">
                <div className="deduction-meta">
                  <div className="feature-name-group">
                    <span className={`type-badge badge-${item.type}`}>
                      {item.type === "additive" ? "🧪 Additive" : "🧂 Nutrient"}
                    </span>
                    <strong className="feature-label">{item.feature}</strong>
                  </div>
                  <span className="deduction-score-pill">
                    {points > 0 ? `+${points}` : points} pts
                  </span>
                </div>

                <div className="deduction-bar-track">
                  <div
                    className={`deduction-bar-fill fill-${item.type}`}
                    style={{ width: `${barWidthPercent}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      )}

      <div className="shap-footer-note">
        <span>ℹ️</span>
        <small>
          Attributions computed via exact Shapley additive explanation values (φᵢ) against baseline whole-food standards.
        </small>
      </div>
    </div>
  );
}

export default ShapAttributionChart;
